/* eslint-disable @typescript-eslint/no-var-requires */
const lastmod = new Date().toISOString();

// Off-sale cards stay in the sitemap but rank below the ones on sale today.
// Instant.json is generated by the crawler, so a missing file must not fail the build.
const expiredPaths = (() => {
  try {
    const instants = require('./src/constant/Instant.json');
    const today = new Date(new Date().toDateString());

    return new Set(
      instants.filter((v) => new Date(v.closedAt) < today).map((v) => `/instant/${v.id}`),
    );
  } catch (e) {
    console.warn('[next-sitemap] Instant.json unavailable, using default priorities');

    return new Set();
  }
})();

// next-sitemap hands `transform` paths without the trailing slash it later adds.
const normalize = (path) => path.replace(/\/+$/, '') || '/';

const isExpired = (path) => expiredPaths.has(normalize(path));

const priority = (path) => {
  if (normalize(path) === '/') return 1.0;
  if (isExpired(path)) return 0.4;

  return 0.8;
};

/** @type {import('next-sitemap').IConfig} */
module.exports = {
  siteUrl: 'https://lottery.celestialstudio.net',
  generateRobotsTxt: true,
  // Write straight into the static export so a single build ships the fresh sitemap.
  outDir: 'out',
  // Keep sitemap URLs identical to the canonical URLs (next.config.js uses trailingSlash).
  trailingSlash: true,
  changefreq: 'weekly',
  // Only HTML pages belong in the sitemap, not static assets like icon.png.
  exclude: ['/icon.png', '/404', '/404/'],
  transform: async (config, path) => ({
    loc: path,
    changefreq: isExpired(path) ? 'monthly' : config.changefreq,
    priority: priority(path),
    lastmod,
  }),
};
